const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=async(path='',body)=>{const r=await fetch('/api/phase-rules'+path,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json','X-Local-Review':'1'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw Error(j.error||'操作未完成');return j;};
let state,original='',busy=false;
const split=v=>v.split('\n').map(v=>v.trim()).filter(Boolean);
const scopeName={all:'整个账户',campaign_name:'Campaign 名称包含',adset_name:'Ad Set 名称包含',name:'Ad 名称包含'};
const messages=[];
function say(who,text){messages.push({who,text});$('#messages').innerHTML=messages.map(m=>`<div class="message ${m.who==='你'?'user':''}"><b>${esc(m.who)}</b>${esc(m.text)}</div>`).join('');$('#messages').scrollTop=$('#messages').scrollHeight;}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);$('#error').textContent='';try{await fn();}catch(e){$('#error').textContent=e.message;}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
function ruleList(){ $('#rules').innerHTML=state.rules.length?state.rules.slice().reverse().map(r=>`<article class="rule"><div class="rule-head"><h3>${esc(r.phase)}</h3><span class="tag">${r.disabled?'已停用':'已确认'}</span></div><p>${esc(scopeName[r.scope_field])} ${r.scope_field==='all'?'':esc(r.scope_value)}<br>${esc(r.start)} 至 ${esc(r.end)} · ${esc(state.timezone)}<br>允许：${esc(r.allow.join('、')||'未设置')}<br>禁用：${esc(r.deny.join('、')||'未设置')}</p><small class="muted">确认人：${esc(r.reviewer)}</small><details><summary>查看原始说明</summary><p>${esc(r.original)}</p></details><div class="actions"><button data-check="${esc(r.id)}">试查已保存文案</button>${!r.disabled?`<button class="secondary" data-disable="${esc(r.id)}">停用本条规则</button>`:''}</div></article>`).join(''):'<p class="muted">还没有确认的阶段规则。聊天内容不会自动生效。</p>';}
function renderDraft(d){original=d.original;$('#draft').innerHTML=`<form id="confirm"><span class="tag">草稿 · 尚未生效</span><label for="phase">阶段名称</label><input id="phase" value="${esc(d.phase)}" placeholder="例如：黑五预热"><div class="row"><div><label for="start">开始日期</label><input id="start" type="date" required></div><div><label for="end">结束日期（含当天）</label><input id="end" type="date" required></div></div><p class="muted">按广告账户时区 ${esc(state.timezone)}。到期后停止使用本规则。</p><label for="scope">适用范围</label><select id="scope" required><option value="">请选择</option value="campaign_name">Campaign 名称包含</option><option value="adset_name">Ad Set 名称包含</option><option value="name">Ad 名称包含</option><option value="all">当前账户全部广告</option></select><input id="scope-value" placeholder="例如：BF 或 de_demo_" aria-label="名称筛选内容"><div class="row"><div><label for="allow">允许使用的词 · 每行一个</label><textarea id="allow" rows="3">${esc(d.allow.join('\n'))}</textarea></div><div><label for="deny">禁止使用的词 · 每行一个</label><textarea id="deny" rows="3">${esc(d.deny.join('\n'))}</textarea></div></div><p class="muted">匹配正文、标题、描述中读到的文字；不区分大小写，按“包含”匹配。禁用词优先，允许词不会让整条广告免检。</p>${d.notes.length?`<details open><summary>以下内容仅记录为背景，不自动检查</summary><p>${d.notes.map(esc).join('<br>')}</p></details>`:''}<label for="reviewer">确认人</label><input id="reviewer" placeholder="你的名字" required><details><summary>先用一段文案测试规则</summary><label for="test-copy">测试文字（不会改广告）</label><textarea id="test-copy" rows="3" placeholder="粘贴一段文案，看是否命中禁用词"></textarea><button type="button" id="test" class="secondary">测试这段文字</button><p id="test-result" role="status"></p></details><label class="check"><input id="ack" type="checkbox" required><span>我已核对日期、范围和关键词。确认只保存检查规则，不会暂停广告。</span></label><button type="submit">确认并保存阶段规则</button></form>`;}
function renderReport(r){const blocked=r.objects.filter(a=>a.hits.length);$('#results').hidden=false;$('#results').innerHTML=`<span class="eyebrow">历史文案试查 · 未修改广告</span><h2>${esc(r.phase)}：${r.forbidden_count?`${r.forbidden_count} 条广告的已存文案命中禁用词`:'已读文案没有命中禁用词'}</h2><div class="notice">配置采集时间：${esc(r.captured_at)}<br>规则当前状态：${esc(r.rule_status)}<br>${esc(r.notice)}</div><div class="metrics"><div><b>${r.scanned}</b><small>历史在投范围内匹配广告</small></div><div><b>${r.forbidden_count}</b><small>命中禁用词</small></div><div><b>${r.no_copy_count}</b><small>没有可读文案</small></div><div><b>${r.partial_count}</b><small>只读到部分文案字段</small></div></div>${r.scanned===0?'<p>没有匹配到广告，请检查范围条件。</p>':''}<p><strong>${r.active_today?'命中后：先用最新配置复查，确认仍违规后列为待暂停，由投手操作。':'该规则当前不生效；试查命中不形成待暂停事项。'}</strong></p>${blocked.map(a=>`<article class="ad"><span class="tag danger">命中禁用词 · 需要最新配置核实</span><h3>Ad：${esc(a.ad)}</h3><p>Ad Set：${esc(a.adset)}<br>Campaign：${esc(a.campaign)}</p>${a.hits.map(h=>`<p>${esc(h.field)}命中「${esc(h.word)}」</p><blockquote>${esc(h.text)}</blockquote>`).join('')}${a.unread_fields.length?`<p class="muted">本条未读到：${a.unread_fields.map(esc).join('、')}；不代表这些字段为空。</p>`:''}</article>`).join('')}<details><summary>查看覆盖明细（${r.objects.length} 条）</summary>${r.objects.map(a=>`<div class="ad"><strong>${esc(a.ad)}</strong><p>${esc(a.campaign)} / ${esc(a.adset)}</p><small>${a.hits.length?'命中禁用词':a.read_fields.length?'已读字段未命中禁用词':'没有可读文案'}${a.unread_fields.length?'；未读到：'+a.unread_fields.map(esc).join('、'):''}</small></div>`).join('')}</details>`;$('#results').scrollIntoView({behavior:'smooth'});}
$('#example').onclick=()=>{$('#message').value='阶段：黑五预热；允许使用“Early Black Friday”；禁止使用“Last chance”和“Ends tonight”。';$('#message').focus();};
$('#chat').onsubmit=e=>{e.preventDefault();run(async()=>{const text=$('#message').value.trim();const d=await api('/draft',{text});say('你',text);say('规则助手',d.message);renderDraft(d);$('#message').value='';});};
document.addEventListener('change',e=>{if(e.target.id==='scope'){$('#scope-value').hidden=e.target.value==='all';if(e.target.value==='all')$('#scope-value').value='';}});
document.addEventListener('submit',e=>{if(e.target.id!=='confirm')return;e.preventDefault();run(async()=>{const rule={original,phase:$('#phase').value,start:$('#start').value,end:$('#end').value,scope_field:$('#scope').value,scope_value:$('#scope-value').value,allow:split($('#allow').value),deny:split($('#deny').value),reviewer:$('#reviewer').value};state=await api('/confirm',{revision:state.revision,rule});ruleList();$('#draft').innerHTML='<div class="empty">规则已保存。<br>点击下方“试查已保存文案”，查看命中原句和广告名称。</div>';say('规则助手','已保存“'+rule.phase+'”。此操作没有修改或暂停广告。你可以继续补充下个阶段的要求。');});});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='test')run(async()=>{const r=await api('/test',{allow:split($('#allow').value),deny:split($('#deny').value),text:$('#test-copy').value});$('#test-result').textContent=r.hits.length?'命中禁用词：'+r.hits.map(h=>h.word).join('、')+'。即使同时出现允许词，也不会放行。':r.read_fields.length?'这段测试文字未命中禁用词。仅验证关键词，不代表整条广告合规。':'请先填写测试文字。';});if(b.dataset.check)run(async()=>renderReport(await api('/check',{rule_id:b.dataset.check})));if(b.dataset.disable)run(async()=>{state=await api('/disable',{revision:state.revision,rule_id:b.dataset.disable});ruleList();$('#results').hidden=true;say('规则助手','这条检查规则已停用，历史记录保留。没有暂停任何广告。');});});
await run(async()=>{state=await api();$('#context').textContent=state.account+' · 本机保存 · 无需登录 · 历史配置采集：'+state.captured_at;ruleList();for(const entry of state.conversation||[]){say('你',entry.draft.original);say('规则助手',entry.draft.message);}const last=state.conversation?.at(-1)?.draft;if(last&&!state.rules.some(r=>r.original===last.original))renderDraft(last);say('规则助手','告诉我当前阶段允许和禁止出现哪些词。建议给关键词加引号，例如：允许使用“Early Black Friday”；禁止使用“Last chance”。我会先整理成确认卡，不会直接让规则生效或暂停广告。');});
